package com.ey.cpqcore.entity;

import com.baomidou.mybatisplus.annotation.IdType;
import com.baomidou.mybatisplus.annotation.TableField;
import com.baomidou.mybatisplus.annotation.TableId;
import com.baomidou.mybatisplus.annotation.TableLogic;
import com.baomidou.mybatisplus.annotation.TableName;
import lombok.Getter;
import lombok.Setter;
import lombok.experimental.Accessors;

import java.io.Serializable;
import java.util.Date;

/**
 * 价目表关联配置方案实体。
 *
 * @author xuezhe
 * @since 2026年07月02日
 */
@Getter
@Setter
@Accessors(chain = true)
@TableName("cpq_price_list_config_solution_relation")
public class PriceListConfigSolutionRelation implements Serializable {

    private static final long serialVersionUID = 1L;

    /**
     * 主键
     */
    @TableId(value = "id", type = IdType.AUTO)
    private Long id;

    /**
     * 价目表编号
     */
    @TableField("price_list_no")
    private String priceListNo;

    /**
     * 配置方案ID
     */
    @TableField("config_solution_id")
    private String configSolutionId;

    /**
     * 方案特性
     */
    @TableField("solution_feature")
    private String solutionFeature;

    /**
     * 机型id
     */
    @TableField("model_id")
    private String modelId;

    /**
     * 机型英文
     */
    @TableField("model_en")
    private String modelEn;

    /**
     * 机型中文
     */
    @TableField("model_ch")
    private String modelCh;

    /**
     * 基本型ID
     */
    @TableField("basic_model_id")
    private String basicModelId;

    /**
     * 创建时间
     */
    @TableField("createdAt")
    private Date createdAt;

    /**
     * 创建人
     */
    @TableField("createdBy")
    private String createdBy;

    /**
     * 创建人名称
     */
    @TableField("createdByName")
    private String createdByName;

    /**
     * 更新时间
     */
    @TableField("updatedAt")
    private Date updatedAt;

    /**
     * 更新人
     */
    @TableField("updatedBy")
    private String updatedBy;

    /**
     * 更新人名称
     */
    @TableField("updatedByName")
    private String updatedByName;

    /**
     * 是否删除
     */
    @TableField("isDeleted")
    @TableLogic
    private Byte isDeleted;
}

