import java.util.List;

/**
 * 价目表 Service。
 *
 * @author xuezhe
 * @since 2026年07月02日
 */
public interface PriceListService extends IService<PriceListEntity> {

    /**
     * 分页查询价目表列表。
     *
     * @param queryDTO 查询参数
     * @return 分页数据
     */
    IPage<PriceListVO> getDataListByPage(PriceListQueryDTO queryDTO);

    /**
     * 保存价目表。
     *
     * @param dto 保存参数
     * @return 价目表编号
     */
    CommonResult<String> savePriceList(PriceListSaveDTO dto);

    /**
     * 根据主键查询价目表详情。
     *
     * @param id 主键
     * @return 详情
     */
    PriceListVO getDetailById(Long id);

    /**
     * 分页查询总部关联子公司价目表。
     *
     * @param queryDTO 查询参数
     * @return 分页数据
     */
    IPage<PriceListVO> getSbsdyPriceList(PriceListSbsdyQueryDTO queryDTO);

    /**
     * 修改价目表状态。
     *
     * @param id 主键
     * @param status 状态
     * @return 处理结果
     */
    CommonResult<String> changeStatus(Long id, Byte status);

    /**
     * 删除价目表。
     *
     * @param id 主键
     * @return 处理结果
     */
    CommonResult<String> deletePriceList(Long id);

    /**
     * 获取配置方案信息
     *
     * @param solutionId 方案ID
     * @param country 国家ID
     * @return 方案详情
     */
    PriceListSolutionPreviewVO preview(String solutionId, String country);

    /**
     * 检查价目表是否存在
     *
     * @param name 价目表名称
     * @return
     */
    boolean checkName(String name);

    /**
     * 价目表价格明细
     *
     * @param queryDTO
     * @return 基本型 + 配置项/配置组合价格明细分页数据
     */
    List<PriceManagementVO> priceDetails(PriceListPriceDetailQueryDTO queryDTO);

    /**
     * 根据出口类型和币种获取区域层级数据
     *
     * @param queryDTO 查询参数
     * @return 区域、细分区域、国家分类、国家层级数据
     */
    List<RegionShowVO> getRegionData(PriceListRegionCountryQueryDTO queryDTO);

    /**
     * 根据出口类型+币种获取区域
     *
     * @param queryDTO
     * @return
     */
    List<PriceListRegionCountryVO> getRegion(PriceListRegionCountryQueryDTO queryDTO);

    /**
     * 根据出口类型+币种+区域获取国家
     * @param queryDTO
     * @return
     */
    List<PriceListRegionCountryVO> getCountry(PriceListRegionCountryQueryDTO queryDTO);
}

