            Map<String, PriceListVO.SolutionInfoVO> solutionInfoMap = new LinkedHashMap<>();
            relationList.forEach(relation -> {
                if (StrUtil.isBlank(relation.getConfigSolutionId())) {
                    return;
                }
                PriceListVO.SolutionInfoVO solutionInfoVO = new PriceListVO.SolutionInfoVO();
                solutionInfoVO.setSolutionId(relation.getConfigSolutionId());
                solutionInfoVO.setSolutionFeature(relation.getSolutionFeature());
                solutionInfoMap.putIfAbsent(relation.getConfigSolutionId(), solutionInfoVO);
            });
            modelConfigSolutionVO.setSolutionInfo(new ArrayList<>(solutionInfoMap.values()));
            result.add(modelConfigSolutionVO);
        });
        return result;
    }

    private void fillCreateAuditFields(PriceListEntity entity) {
        UserAccountShowVO user = UserContext.getUser();
        if (user == null) {
            entity.setCreatedBy(StrUtil.blankToDefault(entity.getCreatedBy(), ""));
            entity.setCreatedByName(StrUtil.blankToDefault(entity.getCreatedByName(), ""));
            entity.setUpdatedBy(StrUtil.blankToDefault(entity.getUpdatedBy(), ""));
            entity.setUpdatedByName(StrUtil.blankToDefault(entity.getUpdatedByName(), ""));
            return;
        }
        entity.setCreatedBy(resolveUserCode(user));
        entity.setCreatedByName(resolveUserName(user));
        entity.setUpdatedBy(resolveUserCode(user));
        entity.setUpdatedByName(resolveUserName(user));
    }

    private void fillCreateAuditFields(PriceListConfigSolutionRelation entity) {
        UserAccountShowVO user = UserContext.getUser();
        if (user == null) {
            entity.setCreatedBy(StrUtil.blankToDefault(entity.getCreatedBy(), ""));
            entity.setCreatedByName(StrUtil.blankToDefault(entity.getCreatedByName(), ""));
            entity.setUpdatedBy(StrUtil.blankToDefault(entity.getUpdatedBy(), ""));
            entity.setUpdatedByName(StrUtil.blankToDefault(entity.getUpdatedByName(), ""));
            return;
        }
        entity.setCreatedBy(resolveUserCode(user));
        entity.setCreatedByName(resolveUserName(user));
        entity.setUpdatedBy(resolveUserCode(user));
        entity.setUpdatedByName(resolveUserName(user));
    }

    private void fillCreateAuditFields(PriceListCountryScope entity) {
        UserAccountShowVO user = UserContext.getUser();
        if (user == null) {
            entity.setCreatedBy(StrUtil.blankToDefault(entity.getCreatedBy(), ""));
            entity.setCreatedByName(StrUtil.blankToDefault(entity.getCreatedByName(), ""));
            entity.setUpdatedBy(StrUtil.blankToDefault(entity.getUpdatedBy(), ""));
            entity.setUpdatedByName(StrUtil.blankToDefault(entity.getUpdatedByName(), ""));
            return;
        }
        entity.setCreatedBy(resolveUserCode(user));
        entity.setCreatedByName(resolveUserName(user));
        entity.setUpdatedBy(resolveUserCode(user));
        entity.setUpdatedByName(resolveUserName(user));
    }

    private void fillUpdateAuditFields(PriceListEntity entity) {
        UserAccountShowVO user = UserContext.getUser();
        if (user == null) {
            entity.setUpdatedBy(StrUtil.blankToDefault(entity.getUpdatedBy(), ""));
            entity.setUpdatedByName(StrUtil.blankToDefault(entity.getUpdatedByName(), ""));
            return;
        }
        entity.setUpdatedBy(resolveUserCode(user));
        entity.setUpdatedByName(resolveUserName(user));
    }

    private String resolveUpdatedDepartment(String value, String fallback) {
        if (StrUtil.isNotBlank(value)) {
            return value;
        }
        if (StrUtil.isNotBlank(fallback)) {
            return fallback;
        }
        UserAccountShowVO user = UserContext.getUser();
        return user == null ? "" : StrUtil.blankToDefault(user.getOwnerDept(), "");
    }

    private String resolveUpdatedDepartmentName(String value, String fallback) {
        if (StrUtil.isNotBlank(value)) {
            return value;
        }
        if (StrUtil.isNotBlank(fallback)) {
            return fallback;
        }
        UserAccountShowVO user = UserContext.getUser();
        return user == null ? "" : StrUtil.blankToDefault(user.getOwnerDeptName(), "");
    }

    private String resolveUserCode(UserAccountShowVO user) {
        if (user == null) {
            return "";
        }
        return StrUtil.equals(user.getUserType(), "1")
                ? StrUtil.blankToDefault(user.getCustNo(), "")
                : StrUtil.blankToDefault(user.getUserCode(), "");
    }

    private String resolveUserName(UserAccountShowVO user) {
        if (user == null) {
            return "";
        }
        return StrUtil.equals(user.getUserType(), "1")
                ? StrUtil.blankToDefault(user.getCnName(), "")
                : StrUtil.blankToDefault(user.getUserName(), "");
    }

    private String formatDateTime(Date date) {
        return new SimpleDateFormat(DATE_TIME_PATTERN).format(date);
    }

    private void executeConfigSolutionBatchInsert(List<PriceListConfigSolutionRelation> relations) {
        splitBatch(relations).forEach(priceListConfigSolutionRelationMapper::insertBatch);
    }

    private void executeCountryScopeBatchInsert(List<PriceListCountryScope> scopes) {
        splitBatch(scopes).forEach(priceListCountryScopeMapper::insertBatch);
    }

    private <T> List<List<T>> splitBatch(List<T> dataList) {
        return CollUtil.split(dataList, RELATION_BATCH_SIZE);
    }

    private boolean isEnglishLocale(String locale) {
        LocaleTypeEnum localeTypeEnum = LocaleTypeEnum.getByCode(locale);
        return localeTypeEnum == LocaleTypeEnum.EN_US;
    }

    private boolean isValidStatus(Byte status) {
        return status != null && status >= 0 && status <= 4;
    }

    private CommonResult<String> validateEffectiveTime(Date effectiveStartTime, Date effectiveEndTime) {
        if (effectiveStartTime == null || effectiveEndTime == null) {
            return null;
        }
        if (effectiveStartTime.after(effectiveEndTime)) {
            return failure("PRICELIST_EFFECTIVE_TIME_INVALID");
        }
        return null;
    }

    private CommonResult<String> failure(String key) {
        return CommonResult.failure(Translator.translate(key));
    }
}

