package com.ey.cpqadmin.controller;

import com.baomidou.mybatisplus.core.metadata.IPage;
import com.ey.cpqcommon.common.CommonResult;
import com.ey.cpqcore.dto.pricelist.*;
import com.ey.cpqcore.service.PriceListService;
import com.ey.cpqcore.vo.PriceManagementVO;
import com.ey.cpqcore.vo.portal.RegionShowVO;
import com.ey.cpqcore.vo.pricelist.PriceListRegionCountryVO;
import com.ey.cpqcore.vo.pricelist.PriceListSolutionPreviewVO;
import com.ey.cpqcore.vo.pricelist.PriceListVO;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

import javax.validation.Valid;
import javax.validation.constraints.NotNull;
import java.util.List;

/**
 * 价目表前端控制器
 *
 * @author xuezhe
 * @since 2026年07月02日
 */
@Validated
@RestController
@RequestMapping("/cpq/priceList")
@Slf4j
@RequiredArgsConstructor
public class PriceListController {

    private final PriceListService priceListService;

    /**
     * 价目表列表
     *
     * @param queryDTO 查询参数
     * @return CommonResult
     */
    @PostMapping("/getDataListByPage")
    public CommonResult<IPage<PriceListVO>> getDataListByPage(@Valid @RequestBody PriceListQueryDTO queryDTO) {
        return CommonResult.success(priceListService.getDataListByPage(queryDTO));
    }

    /**
     * 保存价目表（新增/编辑）
     *
     * @param dto 保存参数
     * @return 价目表编号
     */
    @PostMapping("/savePricelist")
    public CommonResult<String> savePricelist(@Valid @RequestBody PriceListSaveDTO dto) {
        return priceListService.savePriceList(dto);
    }

    /**
     * 价目表详情
     *
     * @param id 主键
     * @return CommonResult
     */
    @GetMapping("/detail")
    public CommonResult<PriceListVO> detail(@NotNull(message = "{PRICELIST_ID_CANNOT_EMPTY}") @RequestParam Long id) {
        PriceListVO vo = priceListService.getDetailById(id);
        if (vo == null) {
            return CommonResult.failure("数据不存在");
        }
        return CommonResult.success(vo);
    }

    /**
     * 总部关联子公司价目表
     *
     * @param queryDTO 查询参数
     * @return CommonResult
     */
    @PostMapping("/getSbsdyPriceList")
    public CommonResult<IPage<PriceListVO>> getSbsdyPriceList(@Valid @RequestBody PriceListSbsdyQueryDTO queryDTO) {
        return CommonResult.success(priceListService.getSbsdyPriceList(queryDTO));
    }

    /**
     * 价目表变更状态
     *
     * @param id 主键
     * @param status 状态
     * @return CommonResult
     */
    @GetMapping("/changeStatus")
    public CommonResult<String> changeStatus(@NotNull(message = "{PRICELIST_ID_CANNOT_EMPTY}") @RequestParam Long id,
                                             @NotNull(message = "{PRICELIST_STATUS_CANNOT_EMPTY}") @RequestParam Byte status) {
        return priceListService.changeStatus(id, status);
    }

    /**
     * 删除价目表
     *
     * @param id 主键
     * @return CommonResult
     */
    @GetMapping("/delete")
    public CommonResult<String> delete(@NotNull(message = "{PRICELIST_ID_CANNOT_EMPTY}") @RequestParam Long id) {
        return priceListService.deletePriceList(id);
    }

    /**
     * 检查价目表名称是否存在
     *
     * @param name 名称
     * @return CommonResult
     */
    @GetMapping("/checkName")
    public CommonResult<Boolean> checkName(@RequestParam("name") String name){
        return CommonResult.success(priceListService.checkName(name));
    }

    /**
     * 价目表预览
     *
     * @param solutionId 配置方案ID
     * @param country 国家ID
     * @return CommonResult
     */
    @GetMapping("/preview")
    public CommonResult<PriceListSolutionPreviewVO> preview(@RequestParam("solutionId") String solutionId,
                                                            @RequestParam("country") String country){
        return CommonResult.success(priceListService.preview(solutionId, country));
    }

    /**
     * 价目表价格明细-弃用
     *
     * @param queryDTO 查询对象
     * @return CommonResult
     */
    @PostMapping("/priceDetails")
    public CommonResult<List<PriceManagementVO>> priceDetails(@RequestBody PriceListPriceDetailQueryDTO queryDTO) {
        List<PriceManagementVO> dataList = priceListService.priceDetails(queryDTO);
        return CommonResult.success(dataList);
    }

    /**
     * 根据出口类型和币种获取区域数据
     *
     * @param exportType 出口类型
     * @param currency 币种
     * @return
     */
    @GetMapping("/getRegionData")
    public CommonResult<List<RegionShowVO>> getRegionData(
            @RequestParam("exportType") String exportType,
            @RequestParam("currency") String currency) {
        PriceListRegionCountryQueryDTO queryDTO = new PriceListRegionCountryQueryDTO();
        queryDTO.setExportType(exportType);
        queryDTO.setCurrency(currency);
        return CommonResult.success(priceListService.getRegionData(queryDTO));
    }

    /**
     * 根据销售类型+币种获取区域-弃用
     *
     * @param queryDTO 查询对象
     * @return CommonResult
     */
    @PostMapping("/getRegion")
    public CommonResult<List<PriceListRegionCountryVO>> getRegion(@RequestBody PriceListRegionCountryQueryDTO queryDTO){
        return CommonResult.success(priceListService.getRegion(queryDTO));
    }

    /**
     * 根据销售类型+币种+区域获取国家-弃用
     *
     * @param queryDTO 查询对象
     * @return CommonResult
     */
    @PostMapping("/getCountry")
    public CommonResult<List<PriceListRegionCountryVO>> getCountry(@RequestBody PriceListRegionCountryQueryDTO queryDTO){
        return CommonResult.success(priceListService.getCountry(queryDTO));
    }

}

